<script lang="ts">import { onMount } from 'svelte'; import { api } from '$lib/api'; import StudentShell from '$lib/components/StudentShell.svelte'; import { apiError, requireStudent, type StudentSession } from '$lib/student-session'; let session: StudentSession | null = null; let profile: any = null; let error = ''; onMount(async () => { session = await requireStudent(); if (!session) return; try { profile = await api('/api/student/profile'); } catch (e) { error = apiError(e); } });</script>
{#if session}<StudentShell {session} active="training"><section class="student-heading"><span class="student-eyebrow">YOUR PRACTICE RECORD</span><h1>TRAINING</h1><p>A focused view of the habits that move your karate forward.</p></section>{#if error}<div class="error">{error}</div>{:else}<div class="student-grid two-column"><section class="student-panel training-hero"><span class="rank-orb large">{profile?.rankName?.slice(0,1) ?? 'TK'}</span><span class="student-eyebrow">CURRENT RANK</span><h2>{profile?.rankName ?? 'White Belt'}</h2><p>{profile?.bio ?? 'Train with patience, precision, and a little more courage than yesterday.'}</p></section><section class="student-panel"><div class="panel-title"><span>CLASS COUNTER</span></div><div class="big-counter">{profile?.totalClasses ?? 0}<small>total check-ins</small></div><div class="progress-track"><span style={`width:${Math.min(100, ((profile?.classesThisMonth ?? 0) / 8) * 100)}%`}></span></div><p class="muted">{profile?.classesThisMonth ?? 0} this month · consistency compounds</p></section></div><section class="student-panel"><div class="panel-title"><span>TRAINING NOTE</span></div><p class="training-note">{profile?.favoriteTechnique ? `Favorite technique: ${profile.favoriteTechnique}.` : 'Your instructor can add training notes and favorite techniques to your profile.'}</p></section>{/if}</StudentShell>{/if}
